<p class="eyebrow">Account</p><div class="page-header"><h1>Notifications</h1><form method="post" action="<?= e(route('dashboard.notifications.read-all')) ?>"><?= app('csrf')->input() ?><button class="button button-secondary">Mark all read</button></form></div><?php if(!$notifications): ?><section class="empty-state"><h2>No notifications</h2><p>Important account and financial updates will appear here.</p></section><?php else: ?><div class="notification-list"><?php foreach($notifications as $notification): ?><article class="card <?= empty($notification['read_at'])?'unread':'' ?>"><h2><?= e($notification['title']) ?></h2><p><?= e($notification['body']) ?></p><small><?= e($notification['created_at']) ?></small><?php $data=json_decode((string)$notification['data'],true)?:[];if(!empty($data['url'])):?><a href="<?= e(url($data['url'])) ?>">Open</a><?php endif; ?><?php if(empty($notification['read_at'])):?><form method="post" action="<?= e(route('dashboard.notifications.read',['notification'=>$notification['id']])) ?>"><?= app('csrf')->input() ?><button class="button button-secondary">Mark read</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
